import fs from 'fs';
import path from 'path';
import {
	PgCopyParseError,
	PgCopyTableReader,
	decodeCopyText,
	parseCopyHeader,
	type PgCopyRow,
} from '../../../src/utils/attachmentCatalog/pgCopyParser';
import {
	ODOO_ATTACHMENT_TARGET,
	attachmentDownloadNames,
	odooAttachmentFromRow,
} from '../../../src/utils/attachmentCatalog/odooAttachments';

// Generated by PostgreSQL 12 pg_dump --format=plain from the synthetic schema in
// odoo-ir-attachment.source.sql (a decoy table sorts before ir_attachment).
const fixture = fs.readFileSync(
	path.join(__dirname, '../../fixtures/attachmentCatalog/odoo-ir-attachment.pg12.sql')
);

const read = (input: Buffer, chunkSize = input.length, target = ODOO_ATTACHMENT_TARGET) => {
	const rows: PgCopyRow[] = [];
	const reader = new PgCopyTableReader(target, row => rows.push(row));
	for (let offset = 0; offset < input.length && !reader.done; offset += chunkSize)
		reader.write(input.subarray(offset, offset + chunkSize));
	reader.end();
	return { rows, reader };
};

describe('PostgreSQL plain dump COPY reader', () => {
	it('reads every ir_attachment row of a real PostgreSQL 12 dump, whatever the chunking', () => {
		const whole = read(fixture);
		expect(whole.rows).toHaveLength(7);
		expect(whole.reader.columns).toContain('index_content');
		for (const size of [1, 2, 3, 7, 64, 4096]) expect(read(fixture, size).rows).toEqual(whole.rows);
		const [first, second, third, fourth] = whole.rows;
		expect(first).toMatchObject({
			id: '1',
			name: 'Faktur_Januari.pdf',
			store_fname: '3f/3f9c2a81e0b7d4c1f2a3b4c5d6e7f8091a2b3c4d',
			res_model: 'account.move',
			res_id: '18342',
			res_field: null,
			file_size: '421888',
			mimetype: 'application/pdf',
			create_date: '2026-01-05 08:15:00',
		});
		// Columns the target does not ask for (index_content, db_datas) are never kept.
		expect(first).not.toHaveProperty('index_content');
		expect(second.name).toBe('Laporan\tTab\nBaris.xlsx');
		expect(third.name).toBe('C:\\Users\\example\\Surat "Resmi".docx');
		expect(fourth.name).toBe('Ringkasan rapat – Q3 ✓.pdf');
		// Odoo 14 has no datas_fname column.
		expect(first).not.toHaveProperty('datas_fname');
	});

	it('never takes a line inside another table for a COPY statement or an end marker', () => {
		const { rows } = read(fixture);
		expect(rows.some(row => row.store_fname === 'de/decoy')).toBe(false);
		expect(rows.map(row => row.id)).toEqual(['1', '2', '3', '4', '5', '6', '7']);
	});

	it('maps rows to filestore attachments and leaves database-stored and URL attachments out', () => {
		const outcomes = read(fixture).rows.map(odooAttachmentFromRow);
		expect(outcomes.map(outcome => outcome.kind)).toEqual([
			'attachment',
			'attachment',
			'attachment',
			'attachment',
			'attachment',
			'not-in-filestore',
			'not-in-filestore',
		]);
		const attachments = outcomes.flatMap(outcome => (outcome.kind === 'attachment' ? [outcome.value] : []));
		expect(attachments[0]).toEqual({
			id: 1,
			name: 'Faktur_Januari.pdf',
			storedPath: '3f/3f9c2a81e0b7d4c1f2a3b4c5d6e7f8091a2b3c4d',
			mimetype: 'application/pdf',
			size: 421888,
			model: 'account.move',
			recordId: 18342,
			field: null,
			created: '2026-01-05 08:15:00',
		});
		// Control characters never reach a name that is shown and used for downloads.
		expect(attachments[1].name).toBe('Laporan Tab Baris.xlsx');
		expect(attachments[4]).toMatchObject({ model: 'product.template', field: 'image_1920' });
	});

	it('prefers the Odoo 12 datas_fname over the free-form name', () => {
		expect(
			odooAttachmentFromRow({
				id: '9',
				name: 'Invoice label',
				datas_fname: 'INV-0009.pdf',
				store_fname: 'ab/abcdef',
				type: 'binary',
			})
		).toMatchObject({ kind: 'attachment', value: { name: 'INV-0009.pdf' } });
	});

	it.each(['../../etc/passwd', '/etc/passwd', 'ab/../cd', 'ab//cd', 'ab/c d', ''])(
		'refuses the stored path %p',
		stored => {
			expect(
				odooAttachmentFromRow({ id: '1', name: 'x', store_fname: stored, type: 'binary' }).kind
			).toBe(stored ? 'invalid' : 'not-in-filestore');
		}
	);

	it('skips a huge value in a column it does not keep, chunk by chunk', () => {
		const huge = 'x'.repeat(20 * 1024 * 1024);
		const dump = Buffer.from(
			'SET client_encoding = \'UTF8\';\n' +
				'COPY public.ir_attachment (id, name, index_content, store_fname) FROM stdin;\n' +
				`1\tbig.pdf\t${huge}\tab/abcdef\n` +
				'\\.\n'
		);
		const { rows } = read(dump, 64 * 1024);
		expect(rows).toEqual([{ id: '1', name: 'big.pdf', store_fname: 'ab/abcdef' }]);
	});

	it('truncates an over-long kept value instead of buffering it', () => {
		const dump = Buffer.from(
			'COPY public.ir_attachment (id, name, store_fname) FROM stdin;\n' +
				`1\t${'n'.repeat(10_000)}\tab/abcdef\n\\.\n`
		);
		const [row] = read(dump, 1000).rows;
		expect(row.name).toHaveLength(ODOO_ATTACHMENT_TARGET.maxFieldBytes);
		expect(row.store_fname).toBe('ab/abcdef');
	});

	it('stops at the end of the target block and ignores the rest of the dump', () => {
		const dump = Buffer.from(
			'COPY public.ir_attachment (id, name, store_fname) FROM stdin;\n1\ta.pdf\tab/1\n\\.\n' +
				'this is not SQL and is never read\n'
		);
		const rows: PgCopyRow[] = [];
		const reader = new PgCopyTableReader(ODOO_ATTACHMENT_TARGET, row => rows.push(row));
		reader.write(dump);
		expect(reader.done).toBe(true);
		expect(() => reader.end()).not.toThrow();
		expect(rows).toHaveLength(1);
	});

	it('reports a dump without the table, a truncated block, missing columns and malformed rows', () => {
		const fail = (text: string) => {
			try {
				read(Buffer.from(text));
			} catch (error) {
				return (error as PgCopyParseError).reason;
			}
			return 'none';
		};
		expect(fail('COPY public.res_partner (id, name) FROM stdin;\n1\tx\n\\.\n')).toBe('table-missing');
		expect(fail('COPY public.ir_attachment (id, name, store_fname) FROM stdin;\n1\ta\tab/1\n')).toBe(
			'truncated'
		);
		expect(fail('COPY public.ir_attachment (id, name) FROM stdin;\n\\.\n')).toBe('columns-missing');
		expect(fail('COPY public.ir_attachment (id, name, store_fname) FROM stdin;\n1\ta\n\\.\n')).toBe(
			'row-malformed'
		);
		expect(
			fail('COPY public.ir_attachment (id, name, store_fname) FROM stdin;\n1\ta\tb\tc\n\\.\n')
		).toBe('row-malformed');
	});

	it('decodes COPY text escapes, octal and hex bytes and the NULL marker', () => {
		const decode = (value: string) => decodeCopyText(Buffer.from(value, 'latin1'));
		expect(decode('\\N')).toBeNull();
		expect(decode('a\\tb\\nc\\\\d')).toBe('a\tb\nc\\d');
		expect(decode('\\303\\251')).toBe('é');
		expect(decode('\\xc3\\xa9')).toBe('é');
		expect(decode('\\b\\f\\r\\v')).toBe('\b\f\r\v');
		expect(decode('\\N\\N')).toBe('NN');
	});

	it('parses quoted and schema-qualified COPY headers', () => {
		expect(parseCopyHeader('COPY public.ir_attachment (id, "name", store_fname) FROM stdin;')).toEqual({
			table: 'public.ir_attachment',
			columns: ['id', 'name', 'store_fname'],
		});
		expect(parseCopyHeader('COPY "public"."ir_attachment" (id) FROM stdin;')?.table).toBe(
			'public.ir_attachment'
		);
		expect(parseCopyHeader('COPY public.ir_attachment TO stdout;')).toBeUndefined();
	});

	it('gives downloads the original name without separators, control characters or quotes', () => {
		expect(attachmentDownloadNames('Ringkasan rapat – Q3 ✓.pdf')).toEqual({
			ascii: 'Ringkasan rapat _ Q3 _.pdf',
			utf8: 'Ringkasan rapat – Q3 ✓.pdf',
		});
		expect(attachmentDownloadNames('..\\..\\secret "x".txt')).toEqual({
			ascii: '__.._secret _x_.txt',
			utf8: '.._.._secret _x_.txt',
		});
		expect(attachmentDownloadNames('')).toEqual({ ascii: 'attachment', utf8: 'attachment' });
	});
});
